#include <iostream>
#include <iomanip>
#include <bitset>
#include <cstdint>

int main() {
    // Portable fixed-width unsigned 32-bit integer
    uint32_t number1 = 960;

    std::cout << "Original value: " << number1 << "\n";
    std::cout << "Binary: " << std::bitset<32>(number1) << "\n\n";

    // Demonstrate left shift
    uint32_t leftShifted = number1 << 8;
    std::cout << "Left shifted 8 bits (number1 << 8): " << leftShifted << "\n";
    std::cout << "Binary: " << std::bitset<32>(leftShifted) << "\n\n";

    // Demonstrate right shift
    uint32_t rightShifted = number1 >> 8;
    std::cout << "Right shifted 8 bits (number1 >> 8): " << rightShifted << "\n";
    std::cout << "Binary: " << std::bitset<32>(rightShifted) << "\n\n";

    // Demonstrate bitwise assignment operators
    // Initial: 0b0011'1100 (60)
    // Step 1: |= (1 << 0) -> 0b0011'1101 (61)
    // Step 2: &= ~(1 << 2) -> 0b0011'1001 (57)
    // Step 3: ^= (1 << 5) -> 0b0001'1001 (25)
    // Step 4: <<= 2 -> 25 * 4 = 100 (0b0110'0100)
    uint32_t flags = 0b0011'1100;
    flags |= (1u << 0);   // Set bit 0
    flags &= ~(1u << 2);  // Clear bit 2
    flags ^= (1u << 5);   // Toggle bit 5
    flags <<= 2;          // Shift left by 2

    std::cout << "Flags after bitwise assignments: " << flags << "\n";
    std::cout << "Binary flags: " << std::bitset<8>(flags) << "\n";

    return 0;
}

body.vi:
Trường bit (bit field) cho phép lập trình viên chỉ định cụ thể số lượng bit mà một thành viên kiểu số nguyên trong `struct` hoặc `union` chiếm dụng. Cú pháp khai báo gồm tên kiểu dữ liệu số nguyên (`unsigned int`, `signed int`, hoặc `bool`), tên thành viên, dấu hai chấm (`:`) và một hằng số nguyên xác định độ rộng bit (width):
```cpp
struct BitCard {
    unsigned int face  : 4; // 4 bit biểu diễn 0-15 (đủ cho 13 mặt từ Át đến K)
    unsigned int suit  : 2; // 2 bit biểu diễn 0-3 (4 chất bài)
    unsigned int color : 1; // 1 bit biểu diễn 0-1 (2 màu)
};
```
Độ rộng bit phải là một hằng số nguyên từ 0 đến số lượng bit tối đa của kiểu dữ liệu cơ sở trên hệ thống.

body.en:
A bit field enables the programmer to explicitly specify the number of bits allocated to an integral member inside a `struct` or `union`. The declaration syntax consists of an integral type (`unsigned int`, `signed int`, or `bool`), the member identifier, a colon (`:`), and an integral constant specifying the width:
```cpp
struct BitCard {
    unsigned int face  : 4; // 4 bits represent 0-15 (enough for 13 faces: Ace to King)
    unsigned int suit  : 2; // 2 bits represent 0-3 (4 suits)
    unsigned int color : 1; // 1 bit represents 0-1 (2 colors)
};
```
The bit width must be an integer constant between 0 and the total number of bits of the underlying integer type on the system.

example.code:
#include <iostream>
#include <iomanip>
#include <array>

// Struct representing a card using bit fields
struct BitCard {
    unsigned int face  : 4; // 4 bits: 0-15 (range 0-12 used for Ace to King)
    unsigned int suit  : 2; // 2 bits: 0-3 (Hearts, Diamonds, Clubs, Spades)
    unsigned int color : 1; // 1 bit: 0-1 (Red, Black)
};

constexpr size_t CARDS = 52;

// Initialize deck using mathematical division and modulo
void fillDeck(std::array<BitCard, CARDS>& deck) {
    for (size_t i = 0; i < CARDS; ++i) {
        deck[i].face = static_cast<unsigned int>(i % (CARDS / 4));
        deck[i].suit = static_cast<unsigned int>(i / (CARDS / 4));
        deck[i].color = static_cast<unsigned int>(i / (CARDS / 2));
    }
}

// Display cards in a clean two-column format
void deal(const std::array<BitCard, CARDS>& deck) {
    std::cout << "Card values 0-12 correspond to Ace through King\n";
    std::cout << "Suit values 0-3 correspond Hearts, Diamonds, Clubs and Spades\n";
    std::cout << "Color values 0-1 correspond to red and black\n\n";

    std::cout << std::left 
              << std::setw(6) << "Card" << std::setw(6) << "Suit" << std::setw(15) << "Color"
              << std::setw(6) << "Card" << std::setw(6) << "Suit" << "Color\n";

    for (size_t k1 = 0; k1 < CARDS / 2; ++k1) {
        size_t k2 = k1 + 26;
        std::cout << std::left
                  << std::setw(6) << deck[k1].face
                  << std::setw(6) << deck[k1].suit
                  << std::setw(15) << deck[k1].color
                  << std::setw(6) << deck[k2].face
                  << std::setw(6) << deck[k2].suit
                  << deck[k2].color << "\n";
    }
}

int main() {
    std::array<BitCard, CARDS> deck{};
    fillDeck(deck);
    deal(deck);
    return 0;
}
